#include <bits/stdc++.h>
using namespace std;

constexpr long long INF = numeric_limits<long long>::max() / 4;

void floyd_warshall(vector<vector<long long>>& dist) {
    int cnt = static_cast<int>(dist.size());

    for (int mid = 0; mid < cnt; ++mid) {
        for (int from = 0; from < cnt; ++from) {
            if (dist[from][mid] == INF) {
                continue;
            }
            for (int to = 0; to < cnt; ++to) {
                if (dist[mid][to] == INF) {
                    continue;
                }
                dist[from][to] = min(dist[from][to],
                    dist[from][mid] + dist[mid][to]);
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, q;
    cin >> n >> m >> q;
    vector<vector<long long>> dist(n,
                                      vector<long long>(n, INF));
    for (int vertex = 0; vertex < n; ++vertex) {
        dist[vertex][vertex] = 0;
    }
    for (int i = 0; i < m; ++i) {
        int first, second;
        long long w;
        cin >> first >> second >> w;
        --first;
        --second;
        dist[first][second] = min(dist[first][second], w);
        dist[second][first] = min(dist[second][first], w);
    }
    floyd_warshall(dist);

    for (int query = 0; query < q; ++query) {
        int from, to;
        cin >> from >> to;
        long long answer = dist[from - 1][to - 1];
        cout << (answer == INF ? -1 : answer) << '\n';
    }
}

